style.css:
@-moz-document url("https://monkeytype.com/") {
/* 1. Set the background wallpaper */
    body {
        background-image: url('https://i.pinimg.com/736x/2f/36/c9/2f36c96d07695a15d5a3727700702c27.jpg') !important;
        background-size: cover !important;
        background-position: center !important;
        background-attachment: fixed !important;
        margin: 0 !important;
        padding: 0 !important;
        font-family: Arial, sans-serif !important;
        color: white !important;
        overflow-x: hidden !important; /* Prevent horizontal scrolling */
    }

    /* 2. Set the logo to pink */
    .logo img {
        filter: hue-rotate(60deg) !important; /* Adjusting logo color to pinkish */
    }

    /* 3. Make the text and elements pink when clicked (punctuation and numbers) */
    .key.clicked, .key:active, .key:focus {
        background-color: pink !important;
        color: black !important;
    }

    /* 4. Make the keys grey when not clicked */
    .key {
        background-color: grey !important;
        color: white !important;
        transition: background-color 0.2s ease, color 0.2s ease !important;
    }

    /* 5. Apply pink color to punctuation and number keys when clicked */
    .key[data-key="1"], .key[data-key="2"], .key[data-key="3"], .key[data-key="4"], .key[data-key="5"], 
    .key[data-key="6"], .key[data-key="7"], .key[data-key="8"], .key[data-key="9"], .key[data-key="0"],
    .key[data-key="!"], .key[data-key="@"], .key[data-key="#"], .key[data-key="$"], .key[data-key="%"],
    .key[data-key="^"], .key[data-key="&"], .key[data-key="*"], .key[data-key="("], .key[data-key=")"], 
    .key[data-key="_"], .key[data-key="+"] {
        background-color: grey !important;
        color: white !important;
    }

    /* 6. Button hover effect */
    .key:hover {
        background-color: #ff69b4 !important; /* Lighter pink on hover */
        color: black !important;
    }

    /* 7. Customize the typing area for better readability */
    .typing-area {
        background-color: rgba(0, 0, 0, 0.5) !important; /* Semi-transparent dark background */
        color: white !important;
        border-radius: 8px !important;
        padding: 10px !important;
    }

    /* 8. Adjust input text color and style */
    .typing-area input {
        background-color: rgba(0, 0, 0, 0.7) !important; /* Dark transparent background for input */
        color: white !important;
        border: none !important;
        padding: 5px !important;
        border-radius: 4px !important;
    }

    /* 9. Customizing other UI elements like buttons */
    .btn, .btn-main {
        background-color: transparent !important;
        border: 2px solid pink !important;
        color: pink !important;
    }

    .btn:hover, .btn-main:hover {
        background-color: pink !important;
        color: black !important;
    }

    /* 10. Transparent background for UI popups */
    .popup, .modal-background {
        background-color: rgba(0, 0, 0, 0.7) !important; /* Dark transparent background for popups */
    }
}
